  class Login extends Component {
     constructor(props){
        super(props);
        this.state = {
           model = {
              login: "",
              password: ""
           }
        }
     }
  render() {
      if (this.props.session.Authenticated) {
        return null;
    }
    return (
        <div>
            <input type="text" value={this.state.model.value.login} onChange={e => this.updateModel(e.target.value, 'login')}placeholder="Username" />
            <input type="password" value={this.state.model.password }onChange={e => this.updateModel(e.target.value, 'password')} placeholder="Password" />
            <input
                type="button"
                value="Login"
                onClick={() => this.props.LoginAction(this.state.model.login, this.state.model.password)}
             />
        </div>
    );
}

 updateModel(value, name){
    var model = extend({}, this.state.model);
    model[name] = value;
    this.setState({model});
  }
}

This mostly depends on the authentication provider you are using, but the default flow would be similar to the following:

//use your logic to make the check
if ( isEmailFromGoogle( email ) )
{
    var props = new AuthenticationProperties
    {
        RedirectUri = callbackUrl,
        Items =
        {
            { "scheme", provider },
            { "returnUrl", returnUrl },
            { "login_hint", email }
        }
    };
    return Challenge( props, "Google" );
}
The "login_hint" property is a special Google login parameter, which you can use to provide tha user's e-mail address to prefill.

The Challenge is a result that will trigger the external authentication provider, in this case Google. It is a kind of HttpUnauthorizedResult and it is built in ASP.NET Core, but also part of the default ASP.NET MVC template when you select user authentication when creating the project.

